const final = {}; 
let mensagens = [];
let primeiroItem = null;

for (const item of items) {
  const json = item.json;

  if (json.Lista && json.Lista.length > 0) {
    json.Lista.forEach(i => {
      let parsed = JSON.parse(i);

      // Salva os textos agrupados (suportando Mensagem ou Messagem)
      if (parsed.Messagem || parsed.Mensagem) {
        mensagens.push(parsed.Messagem || parsed.Mensagem);
      }

      // Resgata os metadados originais da primeira mensagem do pacote
      if (!primeiroItem) {
        primeiroItem = parsed;
      }
    });
  }
}

// Junta as mensagens quebradas
final.Messagem = mensagens.join(', ');

// Se houver um item resgatado, remonta os dados e o telefone
if (primeiroItem) {
  final.From = primeiroItem.From;
  final.Instance = primeiroItem.Instance;
  final.MessagemID = primeiroItem.MessagemID;
  final.timestamp = primeiroItem.timestamp;

  // Extrai e formata o telefone (Regra original do seu fluxo com DDD e o 9)
  if (final.From) {
    const raw = final.From.split('@')[0]; // Ex: 557193643490
    const ddi = raw.slice(0, 2);          // 55
    const ddd = raw.slice(2, 4);          // 71
    let restante = raw.slice(4);          // 93643490

    // Força a inserção do 9 caso o número só tenha 8 dígitos no final
    if (restante.length === 8) {
      restante = '9' + restante;
    }

    final.telefone = `${ddi}${ddd}${restante}`;
  }
}

return [{json: final}];

